17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.nio.charset.StandardCharsets;
20	import java.security.MessageDigest;
21	import java.security.NoSuchAlgorithmException;
22	import java.util.ArrayList;
23	import java.util.Collection;
24	import java.util.List;
25	import java.util.Locale;
26	import java.util.Map;
27	import java.util.regex.Pattern;
28	
29	import org.springframework.http.HttpHeaders;
30	import org.springframework.http.HttpStatus;
31	import org.springframework.http.ResponseEntity;
32	import org.springframework.samples.petclinic.rest.advice.DuplicateHouseholdException;
33	import org.springframework.samples.petclinic.rest.advice.DuplicateTelephoneException;
34	import org.springframework.samples.petclinic.rest.advice.InvalidOwnerFieldsException;
35	import org.springframework.samples.petclinic.mapper.OwnerMapper;
36	import org.springframework.samples.petclinic.mapper.PetMapper;
37	import org.springframework.samples.petclinic.mapper.VisitMapper;
38	import org.springframework.samples.petclinic.model.Owner;
39	import org.springframework.samples.petclinic.model.Pet;
40	import org.springframework.samples.petclinic.model.Visit;
41	import org.springframework.samples.petclinic.rest.api.OwnersApi;
42	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
43	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
44	import org.springframework.samples.petclinic.rest.dto.PetDto;
45	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
46	import org.springframework.samples.petclinic.rest.dto.VisitDto;
47	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
48	import org.springframework.samples.petclinic.service.ClinicService;
49	import org.springframework.security.access.prepost.PreAuthorize;
50	import org.springframework.util.StringUtils;
51	import org.springframework.web.bind.annotation.CrossOrigin;
52	import org.springframework.web.bind.annotation.RequestMapping;
53	import org.springframework.web.bind.annotation.RestController;
54	import org.springframework.web.util.UriComponentsBuilder;
55	
56	import jakarta.transaction.Transactional;
57	
58	/**
59	 * @author Vitaliy Fedoriv
60	 */
61	
62	@RestController
63	@CrossOrigin(exposedHeaders = "errors, content-type")
64	@RequestMapping("/api")
65	public class OwnerRestControllerV1 implements OwnersApi {
66	
67	    private final ClinicService clinicService;
68	
69	    private final OwnerMapper ownerMapper;
70	
71	    private final PetMapper petMapper;
72	
73	    private final VisitMapper visitMapper;
74	
75	    /**
76	     * Pattern for a syntactically valid email address: a non-empty local part, an {@code @},
77	     * and a domain containing at least one dot, with no whitespace in any segment.
78	     */
79	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
80	
81	    /**
82	     * Expansions of the common street-type abbreviations recognised by {@link #normalizeAddress}.
83	     * Keys and values are upper-case, matching the casing the address is folded to before expansion.
84	     */
85	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
86	        "ST", "STREET",
87	        "RD", "ROAD",
88	        "AVE", "AVENUE");
89	
90	    public OwnerRestControllerV1(ClinicService clinicService,
91	                                 OwnerMapper ownerMapper,
92	                                 PetMapper petMapper,
93	                                 VisitMapper visitMapper) {
94	        this.clinicService = clinicService;
95	        this.ownerMapper = ownerMapper;
96	        this.petMapper = petMapper;
97	        this.visitMapper = visitMapper;
98	    }
99	
100	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
101	    @Override
102	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
103	        Collection<Owner> owners;
104	        if (lastName != null) {
105	            owners = this.clinicService.findOwnerByLastName(lastName);
106	        } else {
107	            owners = this.clinicService.findAllOwners();
108	        }
109	        if (owners.isEmpty()) {
110	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
111	        }
112	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
113	    }
114	
115	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
116	    @Override
117	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
118	        Owner owner = this.clinicService.findOwnerById(ownerId);
119	        if (owner == null) {
120	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
121	        }
122	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
123	    }
124	
125	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
126	    @Override
127	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
128	        validateRequiredFields(ownerFieldsDto);
129	        HttpHeaders headers = new HttpHeaders();
130	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
131	        owner.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
132	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
133	            joinHousehold(owner);
134	        } else {
135	            requireUniqueHousehold(owner.getLastName(), owner.getAddress());
136	        }
137	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
138	        requireUniqueTelephone(telephone);
139	        owner.setTelephone(telephone);
140	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
141	        owner.setCustomerCode(generateCustomerCode(owner.getCity(), owner.getLastName()));
142	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
143	        this.clinicService.saveOwner(owner);
144	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
145	        headers.setLocation(UriComponentsBuilder.newInstance()
146	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
147	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
148	    }
149	
150	    /**
151	     * Generates the customer code for a newly created owner, formatted
152	     * {@code '<CITY3>-<LAST3>-<NNNN>'}. {@code CITY3} is the upper-cased first three letters of the
153	     * city, {@code LAST3} the upper-cased first three letters of the last name, and {@code NNNN} a
154	     * per-city, 4-digit zero-padded sequence equal to one more than the number of owners already in
155	     * that city (e.g. {@code 'LON-SMI-0007'}).
156	     *
157	     * @param city the owner's city
158	     * @param lastName the owner's last name
159	     * @return the generated customer code
160	     */
161	    private String generateCustomerCode(String city, String lastName) {
162	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
163	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
164	        int sequence = (int) this.clinicService.findAllOwners().stream()
165	            .filter(existing -> equalsIgnoreCase(existing.getCity(), city))
166	            .count() + 1;
167	        return String.format("%s-%s-%04d", city3, last3, sequence);
168	    }
169	
170	    /**
171	     * Counts the existing owners that already share the given first name and last name, compared
172	     * case-insensitively. This is evaluated before the new owner is saved, so it reflects only the
173	     * owners that existed prior to this create.
174	     *
175	     * @param firstName the first name of the owner being created
176	     * @param lastName the last name of the owner being created
177	     * @return the number of pre-existing namesakes
178	     */
179	    private int countNamesakes(String firstName, String lastName) {
180	        return (int) this.clinicService.findAllOwners().stream()
181	            .filter(existing -> equalsIgnoreCase(existing.getFirstName(), firstName)
182	                && equalsIgnoreCase(existing.getLastName(), lastName))
183	            .count();
184	    }
185	
186	    /**
187	     * Compares two possibly-{@code null} strings for equality, ignoring case. Two {@code null} values
188	     * are considered equal and a {@code null} is never equal to a non-{@code null} value.
189	     *
190	     * @param a the first value, possibly {@code null}
191	     * @param b the second value, possibly {@code null}
192	     * @return whether the values are equal ignoring case
193	     */
194	    private boolean equalsIgnoreCase(String a, String b) {
195	        return a == null ? b == null : a.equalsIgnoreCase(b);
196	    }
197	
198	    /**
199	     * Rejects an owner payload that is missing or blank in any required field. Bean Validation
200	     * (via {@code @Valid}) already rejects {@code null} values and fields that violate their size
201	     * or pattern constraints; this guard additionally rejects whitespace-only values for fields
202	     * (such as address and city) that have no pattern constraint, so that no required field is blank.
203	     *
204	     * @param ownerFieldsDto the submitted owner fields
205	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
206	     */
207	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
208	        List<String> invalidFields = new ArrayList<>();
209	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
210	            invalidFields.add("firstName");
211	        }
212	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
213	            invalidFields.add("lastName");
214	        }
215	        if (!StringUtils.hasText(normalizeAddress(ownerFieldsDto.getAddress()))) {
216	            invalidFields.add("address");
217	        }
218	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
219	            invalidFields.add("city");
220	        }
221	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
222	            invalidFields.add("telephone");
223	        }
224	        if (!invalidFields.isEmpty()) {
225	            throw new InvalidOwnerFieldsException(invalidFields);
226	        }
227	    }
228	
229	    /**
230	     * Normalizes a submitted telephone number to E.164 form and requires the result to be valid. The
231	     * normalized E.164 string (a leading {@code '+'} followed by country code and national digits) is
232	     * what gets stored and returned.
233	     *
234	     * @param telephone the raw telephone value from the request
235	     * @return the normalized E.164 telephone number
236	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number
237	     */
238	    private String normalizeTelephone(String telephone) {
239	        String e164 = toE164(telephone);
240	        if (e164 == null) {
241	            throw new InvalidOwnerFieldsException(List.of("telephone"));
242	        }
243	        return e164;
244	    }
245	
246	    /**
247	     * Converts a telephone value to E.164 form, giving the single authoritative definition of a
248	     * telephone's normalized form. Spaces, dashes and brackets are stripped. A leading {@code '+'}
249	     * and its country code are kept when present; otherwise country code {@code '+61'} is assumed and
250	     * a single leading {@code '0'} is dropped from the national digits. The result is valid only when
251	     * it contains 8 to 15 digits after the {@code '+'}.
252	     *
253	     * <p>Returns {@code null} rather than throwing when the value cannot form a valid E.164 number, so
254	     * it is safe to apply to already-stored (possibly legacy) values when comparing them.
255	     *
256	     * @param telephone the raw telephone value, possibly {@code null}
257	     * @return the E.164 string, or {@code null} if the value cannot form a valid E.164 number
258	     */
259	    private String toE164(String telephone) {
260	        if (telephone == null) {
261	            return null;
262	        }
263	        String cleaned = telephone.replaceAll("[ \\-()]", "");
264	        String digits;
265	        if (cleaned.startsWith("+")) {
266	            digits = cleaned.substring(1);
267	        } else {
268	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
269	            digits = "61" + national;
270	        }
271	        if (!digits.matches("[0-9]{8,15}")) {
272	            return null;
273	        }
274	        return "+" + digits;
275	    }
276	
277	    /**
278	     * Normalizes an optional owner email. An absent (null or blank) email is allowed and yields
279	     * {@code null}. When present, the value must be a syntactically valid address; it is then stored
280	     * and returned lower-cased.
281	     *
282	     * @param email the raw email value from the request, possibly {@code null}
283	     * @return the lower-cased email, or {@code null} when none was supplied
284	     * @throws InvalidOwnerFieldsException if a value is present but not a valid email address
285	     */
286	    private String normalizeEmail(String email) {
287	        if (!StringUtils.hasText(email)) {
288	            return null;
289	        }
290	        String trimmed = email.trim();
291	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
292	            throw new InvalidOwnerFieldsException(List.of("email"));
293	        }
294	        return trimmed.toLowerCase(Locale.ROOT);
295	    }
296	
297	    /**
298	     * Rejects a telephone number whose E.164 form is already used by an existing owner. This enforces
299	     * that no two owners share the same E.164 telephone. Existing values are compared by their E.164
300	     * form; a stored value that cannot form a valid E.164 number is compared as-is.
301	     *
302	     * @param telephone the normalized (E.164) telephone of the owner being created
303	     * @throws DuplicateTelephoneException if another owner already has this E.164 telephone
304	     */
305	    private void requireUniqueTelephone(String telephone) {
306	        boolean inUse = this.clinicService.findAllOwners().stream()
307	            .map(Owner::getTelephone)
308	            .filter(existing -> existing != null)
309	            .map(existing -> {
310	                String e164 = toE164(existing);
311	                return e164 != null ? e164 : existing;
312	            })
313	            .anyMatch(telephone::equals);
314	        if (inUse) {
315	            throw new DuplicateTelephoneException(telephone);
316	        }
317	    }
318	
319	    /**
320	     * Rejects an owner whose last name and address match those of an existing owner, where both are
321	     * compared case-insensitively and with runs of whitespace collapsed to a single space (a shared
322	     * household). The caller skips this check when the request opts in via {@code sharesHousehold}.
323	     *
324	     * @param lastName the last name of the owner being created
325	     * @param address the address of the owner being created
326	     * @throws DuplicateHouseholdException if another owner shares the same last name and address
327	     */
328	    private void requireUniqueHousehold(String lastName, String address) {
329	        if (!findHouseholdMembers(lastName, address).isEmpty()) {
330	            throw new DuplicateHouseholdException(lastName, address);
331	        }
332	    }
333	
334	    /**
335	     * Returns the existing owners that belong to the same household as the given last name and
336	     * address, i.e. those whose last name and address match case-insensitively and with runs of
337	     * whitespace collapsed to a single space.
338	     *
339	     * @param lastName the last name to match
340	     * @param address the address to match
341	     * @return the matching owners (possibly empty, never {@code null})
342	     */
343	    private List<Owner> findHouseholdMembers(String lastName, String address) {
344	        String normalizedLastName = normalizeForHousehold(lastName);
345	        String normalizedAddress = normalizeAddress(address);
346	        return this.clinicService.findAllOwners().stream()
347	            .filter(existing -> normalizeForHousehold(existing.getLastName()).equals(normalizedLastName)
348	                && normalizeAddress(existing.getAddress()).equals(normalizedAddress))
349	            .toList();
350	    }
351	
352	    /**
353	     * Joins the owner being created to the shared household of any existing owner(s) that have the
354	     * same last name and address (compared case-insensitively with collapsed whitespace). Every
355	     * member of the household - the existing owners and the new one - is assigned the same stable
356	     * {@code householdId}, so the shared identifier can be read back from any of them.
357	     *
358	     * <p>When no existing owner shares the household there is nobody to share an identifier with, so
359	     * the owner is left without a {@code householdId}.
360	     *
361	     * @param owner the owner being created, whose {@code householdId} is set when a household is joined
362	     */
363	    private void joinHousehold(Owner owner) {
364	        List<Owner> members = findHouseholdMembers(owner.getLastName(), owner.getAddress());
365	        if (members.isEmpty()) {
366	            return;
367	        }
368	        String householdId = computeHouseholdId(owner.getLastName(), owner.getAddress());
369	        owner.setHouseholdId(householdId);
370	        for (Owner member : members) {
371	            if (!householdId.equals(member.getHouseholdId())) {
372	                member.setHouseholdId(householdId);
373	                this.clinicService.saveOwner(member);
374	            }
375	        }
376	    }
377	
378	    /**
379	     * Computes the stable, shared household identifier for a last name and address. The value is
380	     * derived deterministically from the normalized (case-insensitive, whitespace-collapsed) last
381	     * name and address, so every owner in the same household computes the same identifier.
382	     *
383	     * @param lastName the last name of the household
384	     * @param address the address of the household
385	     * @return the household identifier, formatted {@code 'HH-<12 upper-case hex digits>'}
386	     */
387	    private String computeHouseholdId(String lastName, String address) {
388	        String key = normalizeForHousehold(lastName) + "\n" + normalizeAddress(address);
389	        try {
390	            byte[] digest = MessageDigest.getInstance("SHA-256")
391	                .digest(key.getBytes(StandardCharsets.UTF_8));
392	            StringBuilder hex = new StringBuilder();
393	            for (int i = 0; i < 6; i++) {
394	                hex.append(String.format("%02X", digest[i]));
395	            }
396	            return "HH-" + hex;
397	        } catch (NoSuchAlgorithmException e) {
398	            throw new IllegalStateException("SHA-256 algorithm not available", e);
399	        }
400	    }
401	
402	    /**
403	     * Normalizes a value for case-insensitive, whitespace-collapsed household comparison: leading and
404	     * trailing whitespace is trimmed, any internal run of whitespace is collapsed to a single space,
405	     * and the result is lower-cased. A {@code null} value normalizes to an empty string.
406	     *
407	     * @param value the raw value, possibly {@code null}
408	     * @return the normalized value
409	     */
410	    private String normalizeForHousehold(String value) {
411	        return collapseWhitespace(value).toLowerCase(Locale.ROOT);
412	    }
413	
414	    /**
415	     * Trims leading and trailing whitespace and collapses any internal run of whitespace to a single
416	     * space, giving the single definition of that step shared by the owner normalizers. A {@code null}
417	     * value yields an empty string.
418	     *
419	     * @param value the raw value, possibly {@code null}
420	     * @return the trimmed, whitespace-collapsed value
421	     */
422	    private String collapseWhitespace(String value) {
423	        if (value == null) {
424	            return "";
425	        }
426	        return value.trim().replaceAll("\\s+", " ");
427	    }
428	
429	    /**
430	     * Normalizes an owner's address to its canonical, stored-and-returned form: leading and trailing
431	     * whitespace is trimmed, any internal run of whitespace is collapsed to a single space, the result
432	     * is upper-cased, and common street-type abbreviations are expanded as whole words
433	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} or
434	     * blank-after-collapsing value normalizes to an empty string. The transformation is idempotent, so
435	     * applying it to an already-normalized (or legacy) value is safe when comparing addresses.
436	     *
437	     * @param address the raw address value, possibly {@code null}
438	     * @return the normalized address
439	     */
440	    private String normalizeAddress(String address) {
441	        String collapsed = collapseWhitespace(address).toUpperCase(Locale.ROOT);
442	        if (collapsed.isEmpty()) {
443	            return "";
444	        }
445	        String[] tokens = collapsed.split(" ");
446	        StringBuilder normalized = new StringBuilder();
447	        for (int i = 0; i < tokens.length; i++) {
448	            if (i > 0) {
449	                normalized.append(' ');
450	            }
451	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
452	        }
453	        return normalized.toString();
454	    }
455	
456	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
457	    @Override
458	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
459	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
460	        if (currentOwner == null) {
461	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
462	        }
463	        currentOwner.setAddress(ownerFieldsDto.getAddress());
464	        currentOwner.setCity(ownerFieldsDto.getCity());
465	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
466	        currentOwner.setLastName(ownerFieldsDto.getLastName());
467	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
468	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
469	        this.clinicService.saveOwner(currentOwner);
470	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
471	    }
472	
473	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
474	    @Transactional
475	    @Override
476	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
477	        Owner owner = this.clinicService.findOwnerById(ownerId);
478	        if (owner == null) {
479	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
480	        }
481	        this.clinicService.deleteOwner(owner);
482	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
483	    }
484	
485	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
486	    @Override
487	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
488	        Owner owner = this.clinicService.findOwnerById(ownerId);
489	        if (owner == null) {
490	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
491	        }
492	        HttpHeaders headers = new HttpHeaders();
493	        Pet pet = petMapper.toPet(petFieldsDto);
494	        owner.setId(ownerId);
495	        pet.setOwner(owner);
496	        pet.getType().setName(null);
497	        this.clinicService.savePet(pet);
498	        PetDto petDto = petMapper.toPetDto(pet);
499	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
500	            .buildAndExpand(pet.getId()).toUri());
501	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
502	    }
503	
504	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
505	    @Override
506	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
507	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
508	        if (currentOwner != null) {
509	            Pet currentPet = this.clinicService.findPetById(petId);
510	            if (currentPet != null) {
511	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
512	                currentPet.setName(petFieldsDto.getName());
513	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
514	                this.clinicService.savePet(currentPet);
515	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
516	            }
517	        }
518	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
519	    }
520	
521	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
522	    @Override
523	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
524	        HttpHeaders headers = new HttpHeaders();
525	        Visit visit = visitMapper.toVisit(visitFieldsDto);
526	        Pet pet = new Pet();
527	        pet.setId(petId);
528	        visit.setPet(pet);
529	        this.clinicService.saveVisit(visit);
530	        VisitDto visitDto = visitMapper.toVisitDto(visit);
